{
  "schema_version": "spine_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "title": "Error 404: Hero Not Found",
      "goal": "Survive a fatal real-world accident by glitching into the System's character creation suite.",
      "chapter_role": "hook",
      "stakes_shift": "From mundane mortality to a precarious existence as a system anomaly.",
      "bridge": {
        "from_prev": "N/A",
        "to_next": "Artie enters the tutorial zone with a corrupted, high-variance stat sheet."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 8
      }
    },
    {
      "chapter_id": 2,
      "title": "The Tutorial Tax Evasion",
      "goal": "Exploit the tutorial's reward logic to stack illegal multipliers before leaving the starting zone.",
      "chapter_role": "setup",
      "stakes_shift": "Transition from a lucky survivor to a deliberate exploiter of game mechanics.",
      "bridge": {
        "from_prev": "Artie enters the tutorial zone with a corrupted, high-variance stat sheet.",
        "to_next": "Artie exits the tutorial as a level-one threat to the local power structure."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 3,
      "title": "The Level One Menace",
      "goal": "Defeat the 'unbeatable' scripted guard captain using a physics-breaking loophole.",
      "chapter_role": "trial",
      "stakes_shift": "Local notoriety shifts to a global system flag as an 'unauthorized entity'.",
      "bridge": {
        "from_prev": "Artie exits the tutorial as a level-one threat to the local power structure.",
        "to_next": "The System deploys Sentinels to investigate the combat anomaly."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "rush",
        "expected_scene_count": 9
      }
    },
    {
      "chapter_id": 4,
      "title": "Patch Notes from Hell",
      "goal": "Evade the first wave of System Sentinels by hiding in a 'dead-zone' where the UI fails.",
      "chapter_role": "pressure",
      "stakes_shift": "Survival is no longer about HP, but about staying off the System's radar.",
      "bridge": {
        "from_prev": "The System deploys Sentinels to investigate the combat anomaly.",
        "to_next": "Artie discovers a lead on 'Legacy Code' that can stabilize his existence."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 11
      }
    },
    {
      "chapter_id": 5,
      "title": "The Loot-Cave Incident",
      "goal": "Infiltrate a corrupted dungeon to retrieve a legendary item that shouldn't exist in this version of the game.",
      "chapter_role": "investigation",
      "stakes_shift": "Gaining the leverage needed to negotiate with or fight the System's logic.",
      "bridge": {
        "from_prev": "Artie discovers a lead on 'Legacy Code' that can stabilize his existence.",
        "to_next": "The regional administrator takes a direct interest in Artie's inventory."
      },
      "pacing": {
        "intensity": 3,
        "tempo": "slow_burn",
        "expected_scene_count": 10
      }
    },
    {
      "chapter_id": 6,
      "title": "Breaking the Boss",
      "goal": "Use the glitched legendary item to 'crash' the regional boss and force a system-wide error.",
      "chapter_role": "confrontation",
      "stakes_shift": "Artie moves from a bug to be fixed to a virus that can bring down the server.",
      "bridge": {
        "from_prev": "The regional administrator takes a direct interest in Artie's inventory.",
        "to_next": "The System initiates a forced server-wide maintenance to delete Artie."
      },
      "pacing": {
        "intensity": 5,
        "tempo": "rush",
        "expected_scene_count": 12
      }
    },
    {
      "chapter_id": 7,
      "title": "Unscheduled Maintenance",
      "goal": "Rewrite a local law of reality to create a permanent 'safe-zone' for himself and his loot.",
      "chapter_role": "climax",
      "stakes_shift": "Securing a permanent, if glitched, place in the new world.",
      "bridge": {
        "from_prev": "The System initiates a forced server-wide maintenance to delete Artie.",
        "to_next": "Artie establishes a base of operations, ready for the next patch."
      },
      "pacing": {
        "intensity": 4,
        "tempo": "steady",
        "expected_scene_count": 10
      }
    }
  ]
}

